from dataclasses import dataclass, field
from typing import Dict, List, Optional
import ctypes

@dataclass
class Slab:
    '''Fixed-size object allocator'''
    object_size: int
    count: int = 100

    def __post_init__(self):
        # Allocate contiguous memory
        self.memory = bytearray(self.object_size * self.count)
        # Free list: linked list of available slots
        self.free_list: List[int] = list(range(0, self.object_size * self.count, self.object_size))
        self.allocated = 0

    def allocate(self) -> Optional[int]:
        '''O(1) allocation from free list'''
        if not self.free_list:
            return None
        ptr = self.free_list.pop()
        self.allocated += 1
        return ptr

    def free(self, ptr: int):
        '''O(1) return to free list'''
        self.free_list.append(ptr)
        self.allocated -= 1

    def utilization(self) -> float:
        return self.allocated / self.count

class SlabAllocator:
    '''Multiple slabs for different size classes'''
    def __init__(self):
        self.slabs: Dict[int, Slab] = {}
        self.size_classes = [8, 16, 32, 64, 128, 256]

    def _round_up(self, size: int) -> int:
        '''Find smallest size class that fits'''
        for sc in self.size_classes:
            if sc >= size:
                return sc
        return size  # Fall back to exact size (or could allocate from OS)

    def allocate(self, size: int) -> Optional[int]:
        rounded = self._round_up(size)
        if rounded not in self.slabs:
            self.slabs[rounded] = Slab(object_size=rounded)

        ptr = self.slabs[rounded].allocate()
        if ptr is not None:
            # Store metadata to know which slab on free
            return (rounded, ptr)  # (size_class, offset)
        return None

    def free(self, token):
        size_class, ptr = token
        self.slabs[size_class].free(ptr)

    def stats(self):
        return {size: slab.utilization() for size, slab in self.slabs.items()}

# Demo
allocator = SlabAllocator()

# Allocate various sizes
allocs = []
for size in [10, 20, 30, 50, 100, 200]:
    ptr = allocator.allocate(size)
    allocs.append((size, ptr))
    print(f'Allocated {size} bytes → slab {ptr[0]}, offset {ptr[1]}')

print(f'\nSlab utilization: {allocator.stats()}')

# Free some
for size, ptr in allocs[:3]:
    allocator.free(ptr)
    print(f'Freed {size} bytes from slab {ptr[0]}')

print(f'\nAfter freeing: {allocator.stats()}')
